function arrow(x1,y1,x2,y2,col,wid){
  ctx.strokeStyle=col; ctx.fillStyle=col; ctx.lineWidth=wid;
  ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
  var a=Math.atan2(y2-y1,x2-x1), s=7;
  ctx.beginPath();
  ctx.moveTo(x2,y2);
  ctx.lineTo(x2-s*Math.cos(a-0.4), y2-s*Math.sin(a-0.4));
  ctx.lineTo(x2-s*Math.cos(a+0.4), y2-s*Math.sin(a+0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var th = p.theta * Math.PI / 180;
var cx = W * 0.22, cy = H * 0.72;
var L = Math.min(W, H) * 0.34;
var R = Math.min(W * 0.62, H * 0.72);

// the wire the element sits in
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(cx - L * 0.8, cy); ctx.lineTo(cx + L * 1.9, cy); ctx.stroke();

// the current element
arrow(cx, cy, cx + L, cy, C.accent, 3);
ctx.fillStyle = C.accent;
ctx.fillText("I dl  (current element)", cx + 4, cy + 18);

// r-hat from the element to the field point
var px = cx + R * Math.cos(th), py = cy - R * Math.sin(th);
arrow(cx, cy, px, py, C.figure, 1.5);
ctx.fillStyle = C.figure;
ctx.fillText("r", cx + R * 0.52 * Math.cos(th) - 10, cy - R * 0.52 * Math.sin(th) - 6);

// the angle
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(cx, cy, 34, -th, 0); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("angle " + p.theta.toFixed(0) + " deg", cx + 40, cy - 14 - 22 * Math.sin(th));

// field point
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px, py, 3.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("P", px + 8, py - 6);

// dB at P: out of the page, size proportional to sin(theta)
var s = Math.abs(Math.sin(th));
var rad = 5 + 16 * s;
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(px, py, rad, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(px, py, 2.5 + 2 * s, 0, Math.PI * 2); ctx.fill();
ctx.fillText("dB out of the page", px - 30, py + rad + 16);

// a reminder bar of how big that is
var bx = W * 0.06, by = H * 0.16, bw = W * 0.34;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.strokeRect(bx, by, bw, 10);
ctx.fillStyle = C.accent;
ctx.fillRect(bx, by, bw * s, 10);
ctx.fillStyle = C.ink;
ctx.fillText("dB as a fraction of its largest value", bx, by - 6);

out.note = "sin of the angle = " + s.toFixed(3) + "  -  an element sends nothing straight ahead of itself (0 or 180 deg) and the most out sideways (90 deg)";

function arrow(x1,y1,x2,y2,col,wid){
  ctx.strokeStyle=col; ctx.fillStyle=col; ctx.lineWidth=wid;
  ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
  var a=Math.atan2(y2-y1,x2-x1), s=7;
  ctx.beginPath();
  ctx.moveTo(x2,y2);
  ctx.lineTo(x2-s*Math.cos(a-0.4), y2-s*Math.sin(a-0.4));
  ctx.lineTo(x2-s*Math.cos(a+0.4), y2-s*Math.sin(a+0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var I = p.current, d = p.dist / 100, Lh = p.half / 100;
var sinMax = Lh / Math.sqrt(Lh * Lh + d * d);
var B = 2e-7 * I / d * sinMax;
var Binf = 2e-7 * I / d;

var pad = 30;
var span = Math.max(Lh, d) * 1.25;
var sc = Math.min((W - 2 * pad) / (2 * span), (H - 2 * pad) / (1.5 * span));
var ox = W / 2, oy = H * 0.78;
var X = function (x) { return ox + x * sc; };
var Y = function (y) { return oy - y * sc; };

// full line the wire lies on
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(0, Y(0)); ctx.lineTo(W, Y(0)); ctx.stroke();

// the segment itself
ctx.strokeStyle = C.accent; ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(X(-Lh), Y(0)); ctx.lineTo(X(Lh), Y(0)); ctx.stroke();
arrow(X(0), Y(0), X(0) + 22, Y(0), C.accent, 2);
ctx.fillStyle = C.accent;
ctx.fillText("I = " + I.toFixed(1) + " A", X(0) + 26, Y(0) + 16);

// field point
var Px = X(0), Py = Y(d);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(Px, Py); ctx.lineTo(X(0), Y(0)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(Px, Py, 3.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("P", Px + 8, Py - 6);
ctx.fillText("d = " + (d * 100).toFixed(0) + " cm", Px + 8, (Py + Y(0)) / 2);

// the two end angles
ctx.strokeStyle = C.figure; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(Px, Py); ctx.lineTo(X(Lh), Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(Px, Py); ctx.lineTo(X(-Lh), Y(0)); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("angle to each end", Px + 14, Py + 20);

// travelling element and its contribution
var per = 4.0;
var u = (t % per) / per;
var xs = -Lh + 2 * Lh * u;
var r2 = xs * xs + d * d;
var dB = d / Math.pow(r2, 1.5);
var dBmax = 1 / (d * d);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(xs), Y(0), 4, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(xs), Y(0)); ctx.lineTo(Px, Py); ctx.stroke();
var bar = 4 + 26 * (dB / dBmax);
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(Px, Py, bar, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("size of this element's share", Px + bar + 8, Py + 4);

out.note = "B at P = " + (B * 1e6).toFixed(2) + " microtesla, which is " + (100 * B / Binf).toFixed(1) + " percent of what an endless wire would give (" + (Binf * 1e6).toFixed(2) + " microtesla)";

function arrow(x1,y1,x2,y2,col,wid){
  ctx.strokeStyle=col; ctx.fillStyle=col; ctx.lineWidth=wid;
  ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
  var a=Math.atan2(y2-y1,x2-x1), s=7;
  ctx.beginPath();
  ctx.moveTo(x2,y2);
  ctx.lineTo(x2-s*Math.cos(a-0.4), y2-s*Math.sin(a-0.4));
  ctx.lineTo(x2-s*Math.cos(a+0.4), y2-s*Math.sin(a+0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var R = p.radius / 100, I = p.current, z = p.z / 100, N = p.turns;
var mu = 4 * Math.PI * 1e-7;
var B = mu * N * I * R * R / (2 * Math.pow(R * R + z * z, 1.5));
var B0 = mu * N * I / (2 * R);

// left panel: the loop seen edge on
var ox = W * 0.26, oy = H * 0.5;
var sc = Math.min(W * 0.20 / Math.max(R, 0.01), H * 0.32 / Math.max(R, 0.01));
sc = Math.min(sc, H * 0.30 / Math.max(R, 0.01));
var rr = R * sc;
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(W * 0.46, oy); ctx.stroke();
ctx.fillStyle = C.faint; ctx.fillText("axis", W * 0.40, oy - 6);

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(ox, oy - rr, 5, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(ox, oy + rr, 5, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.ellipse(ox, oy, rr * 0.30, rr, 0, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("loop, R = " + (R * 100).toFixed(0) + " cm", ox - 30, oy + rr + 20);

// field point on the axis
var zpix = Math.min(z * sc, W * 0.19);
var Px = ox + zpix;
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(Px, oy, 3.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("P", Px + 6, oy - 8);
arrow(Px, oy, Px + 26, oy, C.figure, 2);
ctx.fillStyle = C.figure; ctx.fillText("B", Px + 30, oy + 4);

// the two elements whose sideways parts cancel
ctx.strokeStyle = C.rule; ctx.setLineDash([3, 4]); ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(ox, oy - rr); ctx.lineTo(Px, oy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ox, oy + rr); ctx.lineTo(Px, oy); ctx.stroke();
ctx.setLineDash([]);

// right panel: B against z
var gx = W * 0.56, gy = H * 0.16, gw = W * 0.38, gh = H * 0.62;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(gx, gy); ctx.lineTo(gx, gy + gh); ctx.lineTo(gx + gw, gy + gh); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("B on the axis", gx, gy - 6);
ctx.fillText("z", gx + gw - 6, gy + gh + 16);

var zmax = 4 * R;
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var zz = zmax * i / 120;
  var bb = (R * R * R) / Math.pow(R * R + zz * zz, 1.5);
  var gxx = gx + gw * (zz / zmax);
  var gyy = gy + gh - gh * bb;
  if (i === 0) { ctx.moveTo(gxx, gyy); } else { ctx.lineTo(gxx, gyy); }
}
ctx.stroke();

var frac = Math.min(z / zmax, 1);
var curB = (R * R * R) / Math.pow(R * R + z * z, 1.5);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(gx + gw * frac, gy + gh - gh * Math.min(curB, 1), 4, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.faint; ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(gx, gy + gh - gh * Math.min(curB, 1)); ctx.lineTo(gx + gw * frac, gy + gh - gh * Math.min(curB, 1)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("centre value", gx + 4, gy + 12);

out.note = "B = " + (B * 1e6).toFixed(2) + " microtesla at z = " + (z * 100).toFixed(0) + " cm, which is " + (100 * B / B0).toFixed(1) + " percent of the centre value " + (B0 * 1e6).toFixed(2) + " microtesla";

function arrow(x1,y1,x2,y2,col,wid){
  ctx.strokeStyle=col; ctx.fillStyle=col; ctx.lineWidth=wid;
  ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
  var a=Math.atan2(y2-y1,x2-x1), s=7;
  ctx.beginPath();
  ctx.moveTo(x2,y2);
  ctx.lineTo(x2-s*Math.cos(a-0.4), y2-s*Math.sin(a-0.4));
  ctx.lineTo(x2-s*Math.cos(a+0.4), y2-s*Math.sin(a+0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var n = Math.round(p.sides);
var I = p.current, a = p.side / 100;
var mu = 4 * Math.PI * 1e-7;
var d = a / (2 * Math.tan(Math.PI / n));
var Bside = mu * I / (4 * Math.PI * d) * 2 * Math.sin(Math.PI / n);
var B = n * Bside;
var Rcirc = a / (2 * Math.sin(Math.PI / n));
var Bcirc = mu * I / (2 * Rcirc);

var cx = W * 0.32, cy = H * 0.52;
var rad = Math.min(W * 0.24, H * 0.36);
ctx.strokeStyle = C.accent; ctx.lineWidth = 2.5;
ctx.beginPath();
for (var i = 0; i <= n; i++) {
  var ang = -Math.PI / 2 + 2 * Math.PI * i / n;
  var x = cx + rad * Math.cos(ang), y = cy + rad * Math.sin(ang);
  if (i === 0) { ctx.moveTo(x, y); } else { ctx.lineTo(x, y); }
}
ctx.stroke();

// the circle the corners sit on
ctx.strokeStyle = C.faint; ctx.lineWidth = 1; ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.arc(cx, cy, rad, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);

// perpendicular from centre to one side
var a0 = -Math.PI / 2 + Math.PI / n;
var mx = cx + rad * Math.cos(a0) * Math.cos(Math.PI / n);
var my = cy + rad * Math.sin(a0) * Math.cos(Math.PI / n);
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(mx, my); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("d", (cx + mx) / 2 + 6, (cy + my) / 2);

ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fill();
ctx.fillText("centre", cx - 18, cy + 18);
ctx.fillStyle = C.accent;
ctx.fillText(n + " sides, " + (a * 100).toFixed(0) + " cm each", cx - rad, cy - rad - 12);

// bar chart: one side, whole polygon, the circle of the same corner radius
var bx = W * 0.62, by = H * 0.22, bw = W * 0.30, rowh = 22;
var top = Math.max(B, Bcirc);
function row(lab, val, k, col) {
  ctx.fillStyle = C.ink;
  ctx.fillText(lab, bx, by + k * (rowh + 16) - 4);
  ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
  ctx.strokeRect(bx, by + k * (rowh + 16), bw, 12);
  ctx.fillStyle = col;
  ctx.fillRect(bx, by + k * (rowh + 16), bw * (val / top), 12);
  ctx.fillStyle = C.ink;
  ctx.fillText((val * 1e6).toFixed(1) + " uT", bx, by + k * (rowh + 16) + 24);
}
row("one side alone", Bside, 0, C.figure);
row("all " + n + " sides", B, 1, C.accent);
row("circle through the corners", Bcirc, 2, C.rule);

out.note = "polygon centre B = " + (B * 1e6).toFixed(2) + " microtesla; the circle through its corners gives " + (Bcirc * 1e6).toFixed(2) + " microtesla. Raise the number of sides and the two close in on each other.";
